/**
 * @suppress
 */
public object FfiConverterTypeDocument: FfiConverter<Document, Long> {
    override fun lower(value: Document): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): Document {
        return Document(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): Document {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: Document) = 8UL

    override fun write(value: Document, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



/**
 * The save report.
 */
data class Report (
    /**
     * Profile name, e.g. "PDF/UA-1".
     */
    var `profileName`: kotlin.String
    , 
    /**
     * True when all machine checks passed and the file claims PDF/UA.
     */
    var `compliant`: kotlin.Boolean
    , 
    /**
     * Machine-check violations.
     */
    var `violations`: List<Violation>
    , 
    /**
     * Human-review checklist items.
     */
    var `humanReview`: List<kotlin.String>
    , 
    /**
     * The user-facing note; empty when compliant.
     */
    var `note`: kotlin.String
    
){
    

    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeReport: FfiConverterRustBuffer<Report> {
    override fun read(buf: ByteBuffer): Report {
        return Report(
            FfiConverterString.read(buf),
            FfiConverterBoolean.read(buf),
            FfiConverterSequenceTypeViolation.read(buf),
            FfiConverterSequenceString.read(buf),
            FfiConverterString.read(buf),
        )
    }

    override fun allocationSize(value: Report) = (
            FfiConverterString.allocationSize(value.`profileName`) +
            FfiConverterBoolean.allocationSize(value.`compliant`) +
            FfiConverterSequenceTypeViolation.allocationSize(value.`violations`) +
            FfiConverterSequenceString.allocationSize(value.`humanReview`) +
            FfiConverterString.allocationSize(value.`note`)
    )

    override fun write(value: Report, buf: ByteBuffer) {
            FfiConverterString.write(value.`profileName`, buf)
            FfiConverterBoolean.write(value.`compliant`, buf)
            FfiConverterSequenceTypeViolation.write(value.`violations`, buf)
            FfiConverterSequenceString.write(value.`humanReview`, buf)
            FfiConverterString.write(value.`note`, buf)
    }
}



