/**
 * Errors surface as exceptions in Kotlin/Java.
 */
sealed class PdfgenException: kotlin.Exception() {
    
    /**
     * Something failed; `msg` says what.
     */
    class General(
        
        /**
         * Human-readable error message.
         */
        val `msg`: kotlin.String
        ) : PdfgenException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<PdfgenException> {
        override fun lift(error_buf: RustBuffer.ByValue): PdfgenException = FfiConverterTypePdfgenError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypePdfgenError : FfiConverterRustBuffer<PdfgenException> {
    override fun read(buf: ByteBuffer): PdfgenException {
        

        return when(buf.getInt()) {
            1 -> PdfgenException.General(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: PdfgenException): ULong {
        return when(value) {
            is PdfgenException.General -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
        }
    }

    override fun write(value: PdfgenException, buf: ByteBuffer) {
        when(value) {
            is PdfgenException.General -> {
                buf.putInt(1)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



